"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";

const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";

export default function AdminAppointmentsPage() {
  const [appointments, setAppointments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [admin, setAdmin] = useState(null);
  const router = useRouter();

  useEffect(() => {
    checkAuth();
  }, []);

  const checkAuth = () => {
    const token = localStorage.getItem("adminToken");
    const adminData = localStorage.getItem("admin");
    
    console.log("Token:", token);
    console.log("Admin data:", adminData);
    
    // ✅ Fixed: Check if adminData exists and is valid JSON
    if (!token || !adminData || adminData === "undefined" || adminData === "null") {
      console.log("No valid auth data, redirecting to login");
      router.push("/admin/login");
      return;
    }
    
    try {
      // ✅ Fixed: Parse only if valid JSON
      const parsedAdmin = JSON.parse(adminData);
      setAdmin(parsedAdmin);
      fetchAppointments(token);
    } catch (parseError) {
      console.error("Error parsing admin data:", parseError);
      // Clear invalid data and redirect to login
      localStorage.removeItem("adminToken");
      localStorage.removeItem("admin");
      router.push("/admin/login");
    }
  };

  const fetchAppointments = async (token) => {
    try {
      console.log("Fetching appointments with token:", token);
      
      const res = await fetch(`${API_BASE_URL}/api/appointments`, {
        headers: {
          'Authorization': `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        // Token expired or invalid
        logout();
        return;
      }

      if (!res.ok) {
        throw new Error(`Failed to fetch appointments: ${res.status}`);
      }

      const data = await res.json();
      setAppointments(data);
    } catch (error) {
      console.error("Error fetching appointments:", error);
      setError("Failed to load appointments. Please check if the backend is running.");
    } finally {
      setLoading(false);
    }
  };

  const updateStatus = async (id, status) => {
    const token = localStorage.getItem("adminToken");
    
    try {
      const res = await fetch(`${API_BASE_URL}/api/appointments/${id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify({ status }),
      });

      if (res.status === 401) {
        logout();
        return;
      }

      if (!res.ok) throw new Error("Failed to update status");

      // Refresh the list
      fetchAppointments(token);
    } catch (error) {
      console.error("Error updating appointment:", error);
      setError("Failed to update appointment status");
    }
  };

  const logout = () => {
    localStorage.removeItem("adminToken");
    localStorage.removeItem("admin");
    router.push("/admin/login");
  };

  // ✅ Clear any existing invalid data on component mount
  useEffect(() => {
    const adminData = localStorage.getItem("admin");
    if (adminData === "undefined" || adminData === "null") {
      localStorage.removeItem("admin");
      localStorage.removeItem("adminToken");
    }
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading appointments...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm border-b">
        <div className="container mx-auto px-4 py-4">
          <div className="flex justify-between items-center">
            <div>
              <h1 className="text-2xl font-bold text-gray-800">Admin Dashboard</h1>
              <p className="text-gray-600">
                {admin ? `Welcome back, ${admin.name}` : 'Welcome back'}
              </p>
            </div>
            <div className="flex gap-4 items-center">
              {admin && (
                <span className="text-sm text-gray-600">
                  Logged in as: {admin.email}
                </span>
              )}
              <button
                onClick={logout}
                className="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors"
              >
                Logout
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <div className="container mx-auto px-4 py-8">
        {error && (
          <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg mb-6">
            {error}
            <button 
              onClick={() => window.location.reload()}
              className="ml-4 text-sm underline"
            >
              Retry
            </button>
          </div>
        )}

        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-xl font-semibold text-gray-800 mb-6">
            Appointment Requests ({appointments.length})
          </h2>
          
          {appointments.length === 0 ? (
            <div className="text-center py-8">
              <p className="text-gray-500 text-lg">No appointments found.</p>
              <button 
                onClick={() => fetchAppointments(localStorage.getItem("adminToken"))}
                className="mt-4 px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
              >
                Refresh
              </button>
            </div>
          ) : (
            <div className="space-y-6">
              {appointments.map((appt) => (
                <div key={appt._id} className="border border-gray-200 rounded-lg p-6 hover:shadow-md transition-shadow">
                  <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div>
                      <h3 className="font-semibold text-gray-800 mb-2">Client Information</h3>
                      <p><strong>Name:</strong> {appt.fullName}</p>
                      <p><strong>Email:</strong> {appt.email}</p>
                      <p><strong>Phone:</strong> {appt.phone}</p>
                    </div>
                    
                    <div>
                      <h3 className="font-semibold text-gray-800 mb-2">Appointment Details</h3>
                      <p><strong>Service:</strong> {appt.service}</p>
                      <p><strong>Date:</strong> {appt.date}</p>
                      <p><strong>Time:</strong> {appt.time}</p>
                      <p><strong>Status:</strong> 
                        <span className={`ml-2 px-3 py-1 rounded-full text-sm font-medium ${
                          appt.status === 'Approved' ? 'bg-green-100 text-green-800' :
                          appt.status === 'Cancelled' ? 'bg-red-100 text-red-800' :
                          'bg-yellow-100 text-yellow-800'
                        }`}>
                          {appt.status || 'Pending'}
                        </span>
                      </p>
                    </div>
                    
                    <div>
                      <h3 className="font-semibold text-gray-800 mb-2">Actions</h3>
                      <div className="flex flex-wrap gap-2">
                        <button
                          onClick={() => updateStatus(appt._id, 'Approved')}
                          className="px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors text-sm"
                        >
                          Approve
                        </button>
                        <button
                          onClick={() => updateStatus(appt._id, 'Cancelled')}
                          className="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors text-sm"
                        >
                          Cancel
                        </button>
                        <button
                          onClick={() => updateStatus(appt._id, 'Pending')}
                          className="px-4 py-2 bg-yellow-500 text-white rounded-lg hover:bg-yellow-600 transition-colors text-sm"
                        >
                          Pending
                        </button>
                      </div>
                    </div>
                  </div>
                  
                  {appt.message && (
                    <div className="mt-4 pt-4 border-t border-gray-200">
                      <h4 className="font-semibold text-gray-800 mb-2">Client Message:</h4>
                      <p className="text-gray-600 bg-gray-50 p-3 rounded">{appt.message}</p>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}